-- Rebuild Medina Book 4 lesson 6 strictly from the supplied Arabic sharh.
-- Canonical PDF pages: 24-28. DOC text was used only for extraction and checked against the PDF.
begin;

do $migration$
declare
  existing_count integer;
begin
  select count(*) into existing_count
  from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '6';
  if existing_count <> 6 then
    raise exception 'Expected 6 Book 4 lesson 6 rules, found %', existing_count;
  end if;
end $migration$;

with incoming(sort_order, title, content, summary, rule_ar) as (
  values
    (1, 'بَابُ اِفْتَعَلَ (порода اِفْتَعَلَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">بَابُ اِفْتَعَلَ مَزِيدٌ بِهَمْزَةِ الْوَصْلِ وَالتَّاءِ. مَصْدَرُهُ عَلَى وَزْنِ اِفْتِعَالٍ؛ بِكَسْرِ ثَالِثِهِ وَزِيَادَةِ أَلِفٍ قَبْلَ آخِرِهِ. وَمِنْ مَعَانِيهِ الْمُطَاوَعَةُ وَالْمُشَارَكَةُ.</span><p class="rule-study-text">Порода اِفْتَعَلَ содержит добавочные соединительную хамзу и ت. Её масдар строится по модели اِفْتِعَالٌ. Среди объяснённых значений — принятие результата действия и совместное участие.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Термины и русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">حَرْفَا الزِّيَادَةِ: هَمْزَةُ الْوَصْلِ وَالتَّاءُ</span><span class="rule-term-ru">добавочные элементы — соединительная хамза и ت</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ: اِفْتِعَالٌ</span><span class="rule-term-ru">масдар по модели اِفْتِعَالٌ</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">الْمُطَاوَعَةُ</span><span class="rule-term-ru">принятие результата действия</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar ar-tone-subject" dir="rtl" lang="ar">الْمُشَارَكَةُ</span><span class="rule-term-ru">совместное участие</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Образование масдара</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِجْتَمَعَ ← اِجْتِمَاعٌ</span><span class="rule-example-ru">собрался → собрание, встреча</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِنْتَصَرَ ← اِنْتِصَارٌ</span><span class="rule-example-ru">победил → победа</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">الْمُطَاوَعَةُ — принятие результата действия</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">رَفَعْتُ الصَّوْتَ، فَارْتَفَعَ الصَّوْتُ.</span><span class="rule-example-ru">Я повысил голос, и голос повысился.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">مَلَأْتُ الْكُوبَ، فَامْتَلَأَ الْكُوبُ.</span><span class="rule-example-ru">Я наполнил стакан, и стакан наполнился.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">الْمُشَارَكَةُ — совместное участие</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِشْتَرَكَ</span><span class="rule-example-ru">участвовал совместно</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِجْتَمَعَ</span><span class="rule-example-ru">собрался вместе с другими</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِخْتَلَفَ</span><span class="rule-example-ru">разошёлся с другими во мнении</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Производные формы шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمَاضِي</span><span class="rule-table-ru">прошедшее</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمُضَارِعُ</span><span class="rule-table-ru">настояще-будущее</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْأَمْرُ</span><span class="rule-table-ru">повелительное</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ</span><span class="rule-table-ru">масдар</span></th><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-table-ru">действующее причастие</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">اسْمُ الْمَفْعُولِ</span><span class="rule-table-ru">страдательное причастие</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِشْتَرَكَ</span><span class="rule-table-ru">участвовал</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَشْتَرِكُ</span><span class="rule-table-ru">участвует</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِشْتَرِكْ</span><span class="rule-table-ru">участвуй</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِشْتِرَاكٌ</span><span class="rule-table-ru">участие</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُشْتَرِكٌ</span><span class="rule-table-ru">участвующий, участник</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">لَازِمٌ</span><span class="rule-table-ru">глагол непереходный; форма не приводится</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِنْتَهَى</span><span class="rule-table-ru">закончился</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَنْتَهِي</span><span class="rule-table-ru">заканчивается</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِنْتَهِ</span><span class="rule-table-ru">закончи</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِنْتِهَاءٌ</span><span class="rule-table-ru">окончание</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُنْتَهٍ (الْمُنْتَهِي)</span><span class="rule-table-ru">заканчивающийся; определённая форма — الْمُنْتَهِي</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">لَازِمٌ</span><span class="rule-table-ru">глагол непереходный; форма не приводится</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِمْتَحَنَ</span><span class="rule-table-ru">экзаменовал</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَمْتَحِنُ</span><span class="rule-table-ru">экзаменует</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِمْتَحِنْ</span><span class="rule-table-ru">экзаменуй</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِمْتِحَانٌ</span><span class="rule-table-ru">экзамен, испытание</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُمْتَحِنٌ</span><span class="rule-table-ru">экзаменующий</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُمْتَحَنٌ</span><span class="rule-table-ru">экзаменуемый</span></td></tr></tbody></table></div></div></div>', 'Порода اِفْتَعَلَ содержит добавочные соединительную хамзу и ت. Её масдар строится по модели اِفْتِعَالٌ. Среди объяснённых значений — принятие результата действия и совместное участие.', 'بَابُ اِفْتَعَلَ مَزِيدٌ بِهَمْزَةِ الْوَصْلِ وَالتَّاءِ. مَصْدَرُهُ عَلَى وَزْنِ اِفْتِعَالٍ؛ بِكَسْرِ ثَالِثِهِ وَزِيَادَةِ أَلِفٍ قَبْلَ آخِرِهِ. وَمِنْ مَعَانِيهِ الْمُطَاوَعَةُ وَالْمُشَارَكَةُ.'),
    (2, 'الْإِبْدَالُ (замена одного звука другим)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">الْإِبْدَالُ إِحْلَالُ حَرْفٍ مَكَانَ حَرْفٍ آخَرَ. فِي بَابِ اِفْتَعَلَ تُبْدَلُ تَاؤُهُ دَالًا إِذَا كَانَتْ فَاؤُهُ دَالًا أَوْ ذَالًا أَوْ زَايًا، وَتُبْدَلُ طَاءً إِذَا كَانَتْ فَاؤُهُ صَادًا أَوْ ضَادًا أَوْ طَاءً أَوْ ظَاءً. وَإِذَا كَانَتْ فَاؤُهُ وَاوًا أُبْدِلَتِ الْوَاوُ تَاءً، وَإِذَا كَانَتْ هَمْزَةً أَصْلِيَّةً أُبْدِلَتِ الْهَمْزَةُ تَاءً.</span><p class="rule-study-text">Шарх определяет الْإِبْدَالُ как постановку одной буквы на место другой и перечисляет четыре случая замены в породе اِفْتَعَلَ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Термины и русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">إِحْلَالُ حَرْفٍ مَكَانَ حَرْفٍ آخَرَ</span><span class="rule-term-ru">постановка одной буквы на место другой</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar ar-tone-subject" dir="rtl" lang="ar">فَاءُ اِفْتَعَلَ</span><span class="rule-term-ru">первая коренная буква формы اِفْتَعَلَ</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">تَاءُ اِفْتَعَلَ</span><span class="rule-term-ru">добавочная ت формы اِفْتَعَلَ</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Случаи الْإِبْدَالُ в породе اِفْتَعَلَ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">فَاءُ اِفْتَعَلَ</span><span class="rule-table-ru">первая коренная</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحَرْفُ الْمُبْدَلُ</span><span class="rule-table-ru">какая буква заменяется</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْبَدَلُ</span><span class="rule-table-ru">на какую букву</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры и русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">دَالٌ، ذَالٌ، زَايٌ</span><span class="rule-table-ru">د, ذ или ز</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَاءُ اِفْتَعَلَ</span><span class="rule-table-ru">добавочная ت</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">دَالٌ</span><span class="rule-table-ru">заменяется на د</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">دَعَا ← اِدَّعَى؛ زَحَمَ ← اِزْدَحَمَ؛ ذَكَرَ ← اِذْدَكَرَ</span><span class="rule-table-ru">звал → заявил; теснил → столпился; помнил → вспомнил</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">صَادٌ، ضَادٌ، طَاءٌ، ظَاءٌ</span><span class="rule-table-ru">ص, ض, ط или ظ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَاءُ اِفْتَعَلَ</span><span class="rule-table-ru">добавочная ت</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">طَاءٌ</span><span class="rule-table-ru">заменяется на ط</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">صَفَا ← اِصْطَفَى؛ ضَجَعَ ← اِضْطَجَعَ؛ طَلَعَ ← اِطَّلَعَ؛ ظَلَمَ ← اِظْطَلَمَ</span><span class="rule-table-ru">был чистым → избрал; лёг на бок → лёг; взошёл → ознакомился; притеснял → претерпел притеснение</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">وَاوٌ</span><span class="rule-table-ru">первая коренная و</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">وَاوُ الْفِعْلِ</span><span class="rule-table-ru">коренная و</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">تَاءٌ</span><span class="rule-table-ru">заменяется на ت</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">وَصَلَ ← اِتَّصَلَ؛ وَقَى ← اِتَّقَى</span><span class="rule-table-ru">соединил → соединился; оберегал → остерегался</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">هَمْزَةٌ أَصْلِيَّةٌ</span><span class="rule-table-ru">исходная коренная хамза</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْهَمْزَةُ</span><span class="rule-table-ru">коренная хамза</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">تَاءٌ</span><span class="rule-table-ru">заменяется на ت</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَخَذَ ← اِتَّخَذَ</span><span class="rule-table-ru">взял → принял, взял себе</span></td></tr></tbody></table></div></div></div>', 'Шарх определяет الْإِبْدَالُ как постановку одной буквы на место другой и перечисляет четыре случая замены в породе اِفْتَعَلَ.', 'الْإِبْدَالُ إِحْلَالُ حَرْفٍ مَكَانَ حَرْفٍ آخَرَ. فِي بَابِ اِفْتَعَلَ تُبْدَلُ تَاؤُهُ دَالًا إِذَا كَانَتْ فَاؤُهُ دَالًا أَوْ ذَالًا أَوْ زَايًا، وَتُبْدَلُ طَاءً إِذَا كَانَتْ فَاؤُهُ صَادًا أَوْ ضَادًا أَوْ طَاءً أَوْ ظَاءً. وَإِذَا كَانَتْ فَاؤُهُ وَاوًا أُبْدِلَتِ الْوَاوُ تَاءً، وَإِذَا كَانَتْ هَمْزَةً أَصْلِيَّةً أُبْدِلَتِ الْهَمْزَةُ تَاءً.'),
    (3, 'إِذَا الْفُجَائِيَّةُ (إِذَا внезапности — «и вдруг»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-particle" dir="rtl" lang="ar">إِذَا الْفُجَائِيَّةُ حَرْفٌ يُفِيدُ حُدُوثَ أَمْرٍ غَيْرِ مُتَوَقَّعٍ. لَا تَأْتِي فِي أَوَّلِ الْكَلَامِ، وَتَدْخُلُ عَلَى الْجُمْلَةِ الِاسْمِيَّةِ، وَيَجُوزُ الِابْتِدَاءُ بِالنَّكِرَةِ بَعْدَهَا.</span><p class="rule-study-text">إِذَا الْفُجَائِيَّةُ сообщает о внезапном, неожиданном событии. Она не начинает речь, вводит именное предложение, а после неё допустимо неопределённое подлежащее.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Термины и русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar ar-tone-particle" dir="rtl" lang="ar">حُدُوثُ أَمْرٍ غَيْرِ مُتَوَقَّعٍ</span><span class="rule-term-ru">возникновение неожиданного события</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">لَا تَأْتِي فِي أَوَّلِ الْكَلَامِ</span><span class="rule-term-ru">не ставится в начале речи</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar ar-tone-predicate" dir="rtl" lang="ar">تَدْخُلُ عَلَى الْجُمْلَةِ الِاسْمِيَّةِ</span><span class="rule-term-ru">вводит именное предложение</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar ar-tone-subject" dir="rtl" lang="ar">يَجُوزُ الِابْتِدَاءُ بِالنَّكِرَةِ بَعْدَهَا</span><span class="rule-term-ru">после неё можно начать с неопределённого имени</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">خَرَجْتُ فَإِذَا أَسَدٌ بِالْبَابِ.</span><span class="rule-example-ru">Я вышел — и вдруг у двери лев.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">دَخَلْتُ الْفَصْلَ فَإِذَا الْمُدِيرُ جَالِسٌ.</span><span class="rule-example-ru">Я вошёл в аудиторию — и вдруг директор сидит там.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">ظَنَنْتُكَ مُدَرِّسًا فَإِذَا أَنْتَ طَبِيبٌ.</span><span class="rule-example-ru">Я считал тебя преподавателем, а ты вдруг оказался врачом.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿فَأَلۡقَىٰهَا فَإِذَا هِيَ حَيَّةٞ تَسۡعَىٰ﴾</span><span class="rule-example-ru">«Он бросил её — и вдруг она стала змеёй, которая быстро движется».</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَابُ фразы فَإِذَا هِيَ حَيَّةٌ تَسْعَى</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">الْفَاءُ: حَرْفٌ زَائِدٌ لِلتَّوْكِيدِ، وَقِيلَ: لِلْعَطْفِ، وَقِيلَ غَيْرُ ذَلِكَ.</span><span class="rule-example-ru">الْفَاءُ — добавочная частица усиления; также говорится, что она служит для соединения, и приводятся иные мнения.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">إِذَا الْفُجَائِيَّةُ: حَرْفٌ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-example-ru">إِذَا внезапности — неизменяемая на сукуне частица без синтаксического места.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar ar-tone-subject" dir="rtl" lang="ar">هِيَ: ضَمِيرُ رَفْعٍ مُنْفَصِلٌ مَبْنِيٌّ عَلَى الْفَتْحِ فِي مَحَلِّ رَفْعٍ مُبْتَدَأٌ.</span><span class="rule-example-ru">هِيَ — отдельное местоимение именительного разряда, неизменяемое на фатхе, в именительном месте подлежащего.</span></div><div class="rule-example-card rule-term-predicate"><span class="rule-example-ar ar-tone-predicate" dir="rtl" lang="ar">حَيَّةٌ: خَبَرٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ.</span><span class="rule-example-ru">حَيَّةٌ — сказуемое в именительном падеже; показатель — явная дамма.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">وَالْجُمْلَةُ الِاسْمِيَّةُ مِنَ الْمُبْتَدَإِ وَالْخَبَرِ لَا مَحَلَّ لَهَا مِنَ الْإِعْرَابِ.</span><span class="rule-example-ru">Именное предложение из подлежащего и сказуемого не имеет синтаксического места.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar ar-tone-raf" dir="rtl" lang="ar">تَسْعَى: الْجُمْلَةُ الْفِعْلِيَّةُ فِي مَحَلِّ رَفْعٍ نَعْتٌ.</span><span class="rule-example-ru">تَسْعَى — глагольное предложение в именительном месте определения.</span></div></div></div></div>', 'إِذَا الْفُجَائِيَّةُ сообщает о внезапном, неожиданном событии. Она не начинает речь, вводит именное предложение, а после неё допустимо неопределённое подлежащее.', 'إِذَا الْفُجَائِيَّةُ حَرْفٌ يُفِيدُ حُدُوثَ أَمْرٍ غَيْرِ مُتَوَقَّعٍ. لَا تَأْتِي فِي أَوَّلِ الْكَلَامِ، وَتَدْخُلُ عَلَى الْجُمْلَةِ الِاسْمِيَّةِ، وَيَجُوزُ الِابْتِدَاءُ بِالنَّكِرَةِ بَعْدَهَا.'),
    (4, 'ظَنَّ (глагол ظَنَّ — «полагать, считать»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">تَنْصِبُ ظَنَّ مَفْعُولَيْنِ أَصْلُهُمَا الْمُبْتَدَأُ وَالْخَبَرُ. وَيَجُوزُ أَنْ تَدْخُلَ ظَنَّ عَلَى أَنَّ وَأَنْ الْمَصْدَرِيَّتَيْنِ، وَحِينَئِذٍ يَكُونُ الْمَصْدَرُ الْمُؤَوَّلُ فِي مَحَلِّ نَصْبٍ سَادًّا مَسَدَّ مَفْعُولَيْ ظَنَّ.</span><p class="rule-study-text">ظَنَّ ставит два дополнения в винительный падеж; исходно это подлежащее и сказуемое. После ظَنَّ может следовать конструкция с أَنَّ либо أَنْ: образованный масдар занимает место обоих дополнений.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Термины и русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar ar-tone-nasb" dir="rtl" lang="ar">الْمَفْعُولُ بِهِ الْأَوَّلُ</span><span class="rule-term-ru">первое прямое дополнение</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar ar-tone-nasb" dir="rtl" lang="ar">الْمَفْعُولُ بِهِ الثَّانِي</span><span class="rule-term-ru">второе прямое дополнение</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ الْمُؤَوَّلُ</span><span class="rule-term-ru">истолкованный масдар, образованный целой конструкцией</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar ar-tone-predicate" dir="rtl" lang="ar">سَدَّ مَسَدَّ مَفْعُولَيْ ظَنَّ</span><span class="rule-term-ru">занял место двух дополнений ظَنَّ</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Два дополнения и الْمَصْدَرُ الْمُؤَوَّلُ</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">ظَنَنْتُ الطَّالِبَ غَائِبًا.</span><span class="rule-example-ru">Я счёл ученика отсутствующим: الطَّالِبَ — первое дополнение, غَائِبًا — второе.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">ظَنَنْتُ أَنَّ الطَّالِبَ غَائِبٌ.</span><span class="rule-example-ru">Я полагал, что ученик отсутствует: вся конструкция с أَنَّ занимает место двух дополнений.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">مَا ظَنَنْتُ أَنْ يَرْسُبَ الطَّالِبُ.</span><span class="rule-example-ru">Я не думал, что ученик провалится: конструкция أَنْ يَرْسُبَ занимает место двух дополнений.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿وَلَٰكِن ظَنَنتُمۡ أَنَّ ٱللَّهَ لَا يَعۡلَمُ كَثِيرٗا مِّمَّا تَعۡمَلُونَ﴾</span><span class="rule-example-ru">«Но вы полагали, что Аллах не знает многого из того, что вы совершаете».</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿تَظُنُّ أَن يُفۡعَلَ بِهَا فَاقِرَةٞ﴾</span><span class="rule-example-ru">«Она думает, что с нею сделают нечто сокрушительное».</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَابُ предложения يَظُنُّ مُحَمَّدٌ الِامْتِحَانَ قَرِيبًا</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">يَظُنُّ: فِعْلٌ مُضَارِعٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ.</span><span class="rule-example-ru">يَظُنُّ — глагол настояще-будущего времени в изъявительном наклонении; показатель — явная дамма.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar ar-tone-subject" dir="rtl" lang="ar">مُحَمَّدٌ: فَاعِلٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ.</span><span class="rule-example-ru">مُحَمَّدٌ — исполнитель в именительном падеже; показатель — явная дамма.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar ar-tone-nasb" dir="rtl" lang="ar">الِامْتِحَانَ: مَفْعُولٌ بِهِ أَوَّلٌ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.</span><span class="rule-example-ru">الِامْتِحَانَ — первое прямое дополнение в винительном падеже; показатель — явная фатха.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar ar-tone-nasb" dir="rtl" lang="ar">قَرِيبًا: مَفْعُولٌ بِهِ ثَانٍ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.</span><span class="rule-example-ru">قَرِيبًا — второе прямое дополнение в винительном падеже; показатель — явная фатха.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَابُ предложения مَا ظَنَنْتُ أَنْ يَرْسُبَ الطَّالِبُ</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">مَا: حَرْفُ نَفْيٍ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-example-ru">مَا — неизменяемая на сукуне частица отрицания без синтаксического места.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">ظَنَنْتُ: فِعْلٌ مَاضٍ مَبْنِيٌّ عَلَى السُّكُونِ لِاتِّصَالِهِ بِالتَّاءِ الْمُتَحَرِّكَةِ.</span><span class="rule-example-ru">ظَنَنْتُ — глагол прошедшего времени, неизменяемый на сукуне из-за присоединения подвижной ت.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar ar-tone-subject" dir="rtl" lang="ar">وَالتَّاءُ: ضَمِيرُ رَفْعٍ مُتَّصِلٌ مَبْنِيٌّ عَلَى الضَّمِّ فِي مَحَلِّ رَفْعٍ فَاعِلٌ.</span><span class="rule-example-ru">ت — присоединённое местоимение именительного разряда, неизменяемое на дамме, в именительном месте исполнителя.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">أَنْ: حَرْفُ نَصْبٍ وَمَصْدَرٍ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-example-ru">أَنْ — неизменяемая на сукуне частица винительного наклонения и образования масдара, без синтаксического места.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">يَرْسُبَ: فِعْلٌ مُضَارِعٌ مَنْصُوبٌ بِأَنْ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ، وَالْمَصْدَرُ الْمُؤَوَّلُ «أَنْ يَرْسُبَ» فِي مَحَلِّ نَصْبٍ سَادًّا مَسَدَّ مَفْعُولَيْ ظَنَّ.</span><span class="rule-example-ru">يَرْسُبَ — глагол настояще-будущего времени в винительном наклонении после أَنْ с явной фатхой; конструкция أَنْ يَرْسُبَ занимает винительное место двух дополнений ظَنَّ.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar ar-tone-subject" dir="rtl" lang="ar">الطَّالِبُ: فَاعِلٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ.</span><span class="rule-example-ru">الطَّالِبُ — исполнитель в именительном падеже; показатель — явная дамма.</span></div></div></div></div>', 'ظَنَّ ставит два дополнения в винительный падеж; исходно это подлежащее и сказуемое. После ظَنَّ может следовать конструкция с أَنَّ либо أَنْ: образованный масдар занимает место обоих дополнений.', 'تَنْصِبُ ظَنَّ مَفْعُولَيْنِ أَصْلُهُمَا الْمُبْتَدَأُ وَالْخَبَرُ. وَيَجُوزُ أَنْ تَدْخُلَ ظَنَّ عَلَى أَنَّ وَأَنْ الْمَصْدَرِيَّتَيْنِ، وَحِينَئِذٍ يَكُونُ الْمَصْدَرُ الْمُؤَوَّلُ فِي مَحَلِّ نَصْبٍ سَادًّا مَسَدَّ مَفْعُولَيْ ظَنَّ.'),
    (5, 'صِيَغُ الْمُبَالَغَةِ (формы усиленного значения действующего причастия)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">إِذَا أُرِيدَ بِاسْمِ الْفَاعِلِ الدَّلَالَةُ عَلَى الْمُبَالَغَةِ نُقِلَ إِلَى إِحْدَى الصِّيَغِ الْخَمْسِ: فَعَّالٌ، وَفَعِيلٌ، وَفَعُولٌ، وَمِفْعَالٌ، وَفَعِلٌ.</span><p class="rule-study-text">Когда действующему причастию придают значение большой интенсивности или многократности действия, шарх приводит пять специальных моделей.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Пять моделей и все примеры шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْوَزْنُ</span><span class="rule-table-ru">модель</span></th><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">арабские примеры</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعَانِي بِالرُّوسِيَّةِ</span><span class="rule-table-ru">русский смысл каждого примера</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فَعَّالٌ</span><span class="rule-table-ru">модель فَعَّالٌ</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">تَوَّابٌ، غَفَّارٌ، أَكَّالٌ، شَرَّابٌ</span><span class="rule-table-ru">четыре примера этой модели</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">تَوَّابٌ؛ غَفَّارٌ؛ أَكَّالٌ؛ شَرَّابٌ</span><span class="rule-table-ru">многократно принимающий покаяние; многопрощающий; много едящий; много пьющий</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فَعِيلٌ</span><span class="rule-table-ru">модель فَعِيلٌ</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">عَلِيمٌ، سَمِيعٌ، بَصِيرٌ، قَدِيرٌ</span><span class="rule-table-ru">четыре примера этой модели</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">عَلِيمٌ؛ سَمِيعٌ؛ بَصِيرٌ؛ قَدِيرٌ</span><span class="rule-table-ru">всезнающий; всеслышащий; всевидящий; всемогущий</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فَعُولٌ</span><span class="rule-table-ru">модель فَعُولٌ</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">غَفُورٌ، شَكُورٌ، أَكُولٌ، عَبُوسٌ</span><span class="rule-table-ru">четыре примера этой модели</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">غَفُورٌ؛ شَكُورٌ؛ أَكُولٌ؛ عَبُوسٌ</span><span class="rule-table-ru">многопрощающий; много благодарящий; много едящий; сильно хмурящийся</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مِفْعَالٌ</span><span class="rule-table-ru">модель مِفْعَالٌ</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مِعْطَاءٌ، مِقْدَامٌ، مِفْرَاحٌ، مِحْذَارٌ</span><span class="rule-table-ru">четыре примера этой модели</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مِعْطَاءٌ؛ مِقْدَامٌ؛ مِفْرَاحٌ؛ مِحْذَارٌ</span><span class="rule-table-ru">много дающий; очень смелый; много радующийся; очень осторожный</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فَعِلٌ</span><span class="rule-table-ru">модель فَعِلٌ</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">حَذِرٌ، فَطِنٌ، جَزِعٌ، فَرِحٌ، مَزِقٌ</span><span class="rule-table-ru">пять примеров этой модели</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">حَذِرٌ؛ فَطِنٌ؛ جَزِعٌ؛ فَرِحٌ؛ مَزِقٌ</span><span class="rule-table-ru">крайне осторожный; очень проницательный; сильно тревожащийся; очень радующийся; много рвущий</span></td></tr></tbody></table></div></div></div>', 'Когда действующему причастию придают значение большой интенсивности или многократности действия, шарх приводит пять специальных моделей.', 'إِذَا أُرِيدَ بِاسْمِ الْفَاعِلِ الدَّلَالَةُ عَلَى الْمُبَالَغَةِ نُقِلَ إِلَى إِحْدَى الصِّيَغِ الْخَمْسِ: فَعَّالٌ، وَفَعِيلٌ، وَفَعُولٌ، وَمِفْعَالٌ، وَفَعِلٌ.'),
    (6, 'دَخَلَهُ وَدَخَلَ فِيهِ (управление глагола دَخَلَ — без فِي и с فِي)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-jarr" dir="rtl" lang="ar">إِذَا كَانَ الْمَدْخُولُ مَكَانًا عُدِّيَ الْفِعْلُ دَخَلَ بِنَفْسِهِ مِنْ غَيْرِ حَرْفِ الْجَرِّ فِي، وَإِذَا لَمْ يَكُنِ الْمَدْخُولُ مَكَانًا عُدِّيَ بِحَرْفِ الْجَرِّ فِي.</span><p class="rule-study-text">Когда после دَخَلَ называется место, глагол присоединяет его непосредственно. Если речь не о месте, шарх требует предлог فِي.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Два типа управления</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَوْعُ الْمَدْخُولِ</span><span class="rule-table-ru">что обозначает зависимое слово</span></th><th><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">التَّعْدِيَةُ</span><span class="rule-table-ru">способ присоединения</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَكَانٌ</span><span class="rule-table-ru">место</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">بِدُونِ حَرْفِ الْجَرِّ فِي</span><span class="rule-table-ru">без предлога فِي</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">دَخَلْتُ الْغُرْفَةَ.</span><span class="rule-table-ru">Я вошёл в комнату.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَكَانٌ</span><span class="rule-table-ru">место</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">بِدُونِ حَرْفِ الْجَرِّ فِي</span><span class="rule-table-ru">без предлога فِي</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">دَخَلْتُ الْمَسْجِدَ.</span><span class="rule-table-ru">Я вошёл в мечеть.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">غَيْرُ مَكَانٍ</span><span class="rule-table-ru">не место</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">بِحَرْفِ الْجَرِّ فِي</span><span class="rule-table-ru">с предлогом فِي</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">دَخَلْتُ فِي الِامْتِحَانِ.</span><span class="rule-table-ru">Я вступил в экзамен, приступил к нему.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">غَيْرُ مَكَانٍ</span><span class="rule-table-ru">не место</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">بِحَرْفِ الْجَرِّ فِي</span><span class="rule-table-ru">с предлогом فِي</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">دَخَلْتُ فِي الْإِسْلَامِ.</span><span class="rule-table-ru">Я вошёл в ислам.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранические примеры шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿وَدَخَلَ جَنَّتَهُۥ﴾</span><span class="rule-example-ru">«И вошёл он в свой сад»: جَنَّتَهُ — место, поэтому стоит без فِي.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿يَدۡخُلُونَ فِي دِينِ ٱللَّهِ أَفۡوَاجٗا﴾</span><span class="rule-example-ru">«Входят в религию Аллаха толпами»: دِينِ اللَّهِ — не место, поэтому употреблён предлог فِي.</span></div></div></div></div>', 'Когда после دَخَلَ называется место, глагол присоединяет его непосредственно. Если речь не о месте, шарх требует предлог فِي.', 'إِذَا كَانَ الْمَدْخُولُ مَكَانًا عُدِّيَ الْفِعْلُ دَخَلَ بِنَفْسِهِ مِنْ غَيْرِ حَرْفِ الْجَرِّ فِي، وَإِذَا لَمْ يَكُنِ الْمَدْخُولُ مَكَانًا عُدِّيَ بِحَرْفِ الْجَرِّ فِي.')
)
update public.rules as r
set title = incoming.title,
    content = incoming.content,
    rule_kind = 'rule',
    summary = incoming.summary,
    rule_ar = incoming.rule_ar
from incoming
where r.course_name = 'Мединский курс (Том 4)'
  and r.lesson_number = '6'
  and r.sort_order = incoming.sort_order;

delete from public.rule_sources
where rule_id in (
  select id from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '6'
);

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'الدَّرْسُ السَّادِسُ
بَـابُ اِفْتَعَلَ
من أمثلته : اِجْتَمَعَ ، اِنْتَصَرَ ، اِشْتَرَكَ ، اِنْتَهَى .
حرفا الزيادة : الهمزة ، والتاء .
مصدره : اِفْتِعَالٌ ( كسرُ ثالثه ، وزيادة ألف قبل آخره ) .
نحو : اِجْتَمَعَ  : اِجْتِمَاعٌ ، اِنْتَصَرَ : اِنْتِصَارٌ .
من معانيه :
1- الْمُطَاوَعَةُ : نحو : رفعتُ الصَّوتَ، فارتفعَ الصَّوتُ . ملأتُ الكُوبَ، فامْتَلأَ الكُوبُ .
2- الْمُشَارَكَةُ : نحو : اشْتَرَكَ ، اجْتَمَعَ ، اخْتَلَفَ .
المشتقات :
اسم المفعول
| اسم الفاعل
