|', 24, 24, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '6' and sort_order = 1;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'الإِبْدَالُ
الإبدال ، هو : إحْلاَلُ حرفٍ مكانَ حرفٍ آخرَ .
القاعدة :
1- إذا كانت فاء افتَعَل ( دالاً ، أو ذالاً ، أو زاياً ) أبدلت تاؤه ( دالاً ) .
نحو : دَعَا : ادَّعَى -  زَحَمَ :  ازْدَحَمَ - ذَكَرَ : اذْدَكَرَ
2- إذا كانت فاء افتعل ( صاداً , أو ضاداً , أو طاءً , أو ظاءً ) أبدلت تاؤه ( طاءً ) .
نحو : صَفَا : اصْطَفَى - ضَجَعَ  : اضْطَجَعَ - طَلَعَ : اطَّلَعَ - ظَلَمَ : اظْطَلَمَ .
3- إذا كانت فاء افتعل ( واواً ) أُبْدِلَت الواو ( تاء ) .
نحو : وَصَلَ : اتَّصَلَ - وَقَى : اتَّقَى .
وكذلك إذا كانت فاء افتعل ( همزة أصلية ) تُبدل الهمزة تاء ، نحو : أخذَ : اِتَّخَذَ .', 24, 25, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '6' and sort_order = 2;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'إِذَا الفُجَائِيَّةُ
إذا الفجائية : حرف يُفِيدُ حُدَوثَ أَمْرٍ غَيْرِ مُتَوَقَّعٍ .
لا تأتي إذا الفجائية في أول الكلام . تدخل على الجملة الاسمية ( المبتدأ والخبر ) ويجوز الابتداء بالنكرة بعدها .
الأمثلة :
خرجتُ فإذا أسدٌ بالباب . دخلت الفصل فإذا المديرُ جالسٌ .
ظَنَنْتُكَ مُدرساً فإذا أنتَ طبيبٌ .
قال تعالى : ﴿ فَأَلْقَاهَا فَإِذَا هِيَ حَيَّةٌ تَسْعَى ﴾ .
الإعراب : ﴿ فَإِذَا هِيَ حَيَّةٌ تَسْعَى ﴾
الفاء : حرف زائد للتوكيد . وقيل للعطف ، وقيل غير ذلك .
إذا الفجائية : حرف مبني على السكون لا محل له من الإعراب .
هي : ضمير رفع منفصل مبني على الفتح في محل رفع مبتدأ .
حيَّةٌ : خبر مرفوع و علامة رفعه الضمة الظاهرة .
والجملة الاسمية من المبتدأ والخبر لا محل لها من الإعراب .
تسعى : الجملة الفعليَّة في محلِّ رفع نعت .', 25, 26, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '6' and sort_order = 3;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'ظَنَّ
تَنْصِبُ ظَنَّ مفعولين أصلهما المبتدأ ، والخبر .
نحو : ظننت الطالبَ غائبا . فـ ( الطالب) مفعول به أول , و( غائبا ) مفعول به ثانٍ .
يجوز أن تدخل ظنَّ على ( أنَّ ، وأنْ ) المصدريتين ، وحينئذ يكون المصدر المؤول في محل نصب سَدَّ مَسَدَّ مفعولي ظَنَّ ، نحو : ظننت أنَّ الطالبَ غائبٌ .
فالمصدر المؤول ( أنّ الطالبَ غائبٌ ) في محل نصب سَدَّ مَسَدَّ مفعولي ظنَّ ، أي : وقع موقعهما . ونحو : ما ظننت أَنْ يرسبَ الطالبُ ، فالمصدر المؤول ( أَنْ يرسبَ ) في محل نصب سدّ مسدّ مفعولي ظنّ . ومنه قوله تعالى : ﴿ وَلَكِنْ ظَنَنْتُمْ أَنَّ اللَّهَ لَا يَعْلَمُ كَثِيرًا مِمَّا تَعْمَلُونَ ﴾ وقوله تعالى : ﴿ تَظُنُّ أَنْ يُفْعَلَ بِهَا فَاقِرَةٌ ﴾ .
الإعراب :
* يَظُنُّ محمدٌ الامتحانَ قريباً .
يظنُّ : فعل مضارع مرفوع وعلامة رفعه الضمة الظاهرة .
محمدٌ : فاعل مرفوع وعلامة رفعه الضمة الظاهرة .
الامتحانَ : مفعول به أوَّل منصوب وعلامة نصبه الفتحة الظاهرة .
قريباً : مفعول به ثانٍ منصوب وعلامة نصبه الفتحة الظاهرة .
* ما ظَنَنْتُ أن يرسُبَ الطَّالبُ .
ما : حرف نفي مبني على السكون لا محل له من الإعراب .
ظَنَنْتُ : فعل ماضِ مبني على السكون لا تصاله بالتاء المتحركة .
والتاء : ضمير رفع متصل مبني على الضم في محل رفع فاعل .
أَنْ : حرف نصب ومصدر مبني على السكون لا محل له من الإعراب .
يرسبَ : فعل مضارع منصوب بأَنْ وعلامة نصبه الفتحة الظاهرة ، والمصدر المؤوَّل
( أن يرسب ) في محل نصب سدَّ مسدَّ مفعولي ظنّ .
الطَّالبُ : فاعل مرفوع وعلامة رفعه الضمة الظاهرة .', 26, 27, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '6' and sort_order = 4;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'صِيَغُ الْمُبَالَغَةِ
إذا أُرِيدَ باسمِ الفاعلِ الدَّلالةُ على المبالغةِ نُقِلَ إلى إحدى الصيغ الآتية :
1- فَعَّالٌ : تَوَّابٌ ، غَفَّارٌ ؛ أَكَّالٌ ، شَرَّابٌ .
2- فَعِيْلٌ : عَلِيْمٌ ، سَمِيْعٌ ، بَصِيرٌ ، قَدِيرٌ .
3- فَعُوْلٌ : غَفُورٌ ، شَكُورٌ ؛ أَكُولٌ ، عَبُوسٌ .
4- مِفْعَالٌ : مِعْطَاءٌ ، مِقْدَامٌ ، مِفْرَاحٌ ، مِحْذَارٌ .
5- فَعِلٌ : حَذِرٌ ، فَطِنٌ ، جَزِعٌ ، فَرِحٌ ، مَزِقٌ .', 27, 27, 1
from public.rules
