insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'دَخَلَهُ , ودَخَلَ فِيهِ
إذا كان المدخولُ مَكَاناً , قلتَ : دخلتُ الغرفةَ ، ودخلتُ المسجدَ . ومنه قوله تعالى : ﴿ وَدَخَلَ جَنَّتَهُ ﴾ تقول ذلك بدون حرف الجر ( في ) .
أما إذا لم يكن المدخولُ مكاناً ؛ فتقول : دخلتُ في الامْتِحَانِ ، ودخلتُ في الإسلامِ ،
ومنه قوله تعالى : ﴿ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا ﴾ تقول ذلك بحرف الجر ( في ) .', 27, 28, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '6' and sort_order = 6;

do $migration$
declare
  updated_count integer;
  source_count integer;
begin
  select count(*) into updated_count
  from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '6' and rule_ar is not null and btrim(rule_ar) <> '';
  select count(*) into source_count
  from public.rule_sources rs
  join public.rules r on r.id = rs.rule_id
  where r.course_name = 'Мединский курс (Том 4)' and r.lesson_number = '6';
  if updated_count <> 6 or source_count <> 6 then
    raise exception 'Book 4 lesson 6 QA failed: rules %, sources %', updated_count, source_count;
  end if;
end $migration$;

commit;
